<section class="page-hero page-hero-compact"><div class="container"><span class="eyebrow">EMPLOYER SPACE</span><h1>Organization dashboard</h1><p>Manage your opportunities and review applications from your organization.</p></div></section>
<section class="section"><div class="container">
    <?php if (count($organizations) > 1): ?><form class="organization-switcher" method="get" action="<?= e(basePath()) ?>/index.php"><input type="hidden" name="page" value="employer"><label class="field"><span>Manage organization</span><select name="organization_id"><?php foreach ($organizations as $availableOrganization): ?><option value="<?= e($availableOrganization['id']) ?>" <?= (int) $availableOrganization['id'] === (int) $organization['id'] ? 'selected' : '' ?>><?= e($availableOrganization['name']) ?><?= (bool) $availableOrganization['is_owner'] ? ' (owner)' : ' (representative)' ?></option><?php endforeach; ?></select></label><button class="button button-outline" type="submit">Switch organization</button></form><?php endif; ?>
    <div class="dashboard-summary"><article class="summary-card"><span>Organization verification</span><strong class="summary-status"><?= e(ucfirst($organization['verification_status'] ?? 'Profile needed')) ?></strong><p><?= $organization ? 'Verification helps candidates build trust.' : 'Complete your organization profile to get started.' ?></p></article><article class="summary-card summary-blue"><span>Open listings</span><strong><?= e($stats['published']) ?></strong></article><article class="summary-card summary-plum"><span>Pending review</span><strong><?= e($stats['pending']) ?></strong></article><article class="summary-card summary-pink"><span>Applications received</span><strong><?= e($stats['applications']) ?></strong></article></div>
    <?php if ($organization): ?><section class="panel organization-panel"><div class="panel-heading"><div><span class="eyebrow">ORGANIZATION PROFILE</span><h2><?= e($organization['name']) ?></h2></div><span class="status status-<?= e($organization['verification_status']) ?>"><?= e(ucfirst($organization['verification_status'])) ?></span></div><p><?= e($organization['description'] ?: 'Add a description to help candidates learn about your organization.') ?></p><?php if ((bool) $organization['is_owner'] && in_array($organization['verification_status'], ['unverified','rejected'], true)): ?><form method="post" action="<?= e(pageUrl('employer')) ?>"><?= formToken() ?><input type="hidden" name="action" value="request_verification"><label class="field"><span>Verification details</span><textarea name="verification_details" rows="2" maxlength="2000" required placeholder="Share your official registration or organization details."></textarea></label><button class="button button-outline" type="submit">Request verification</button></form><?php endif; ?></section><?php endif; ?>
    <?php if ($organization && (bool) $organization['is_owner']): ?><section class="panel organization-panel"><div class="panel-heading"><div><span class="eyebrow">TEAM ACCESS</span><h2>Organization representatives</h2></div></div><p class="muted">Representatives need an active employer account. They can view applications and candidate documents for this organization.</p><form class="inline-form representative-form" method="post" action="<?= e(pageUrl('employer')) ?>"><?= formToken() ?><input type="hidden" name="action" value="add_organization_representative"><label class="field"><span>Employer account email</span><input type="email" name="email" maxlength="190" required></label><label class="field"><span>Role title</span><input name="role_title" maxlength="100" placeholder="Recruiter"></label><button class="button button-outline" type="submit">Add representative</button></form><?php if ($representatives !== []): ?><div class="institution-list"><?php foreach ($representatives as $representative): ?><div><strong><?= e($representative['full_name']) ?></strong><span><?= e($representative['email']) ?><?= $representative['role_title'] ? ' · ' . e($representative['role_title']) : '' ?></span><form method="post" action="<?= e(pageUrl('employer')) ?>"><?= formToken() ?><input type="hidden" name="action" value="remove_organization_representative"><input type="hidden" name="user_id" value="<?= e($representative['id']) ?>"><button class="button button-text" type="submit">Remove</button></form></div><?php endforeach; ?></div><?php endif; ?></section><?php endif; ?>
    <div class="section-heading dashboard-section-heading"><div><span class="eyebrow">OPPORTUNITY MANAGEMENT</span><h2>Your opportunities</h2></div><?php if (!$organization || (bool) $organization['is_owner']): ?><a class="button button-primary" href="<?= e(pageUrl('opportunity-form')) ?>">Create opportunity</a><?php endif; ?></div>
    <div class="panel">
        <?php if ($opportunities === []): ?><div class="empty-state"><h2>No opportunities yet</h2><p><?= $organization && !(bool) $organization['is_owner'] ? 'There are no opportunities listed for this organization yet.' : 'Create a draft, then submit it for administrator review before it is published.' ?></p><?php if (!$organization || (bool) $organization['is_owner']): ?><a class="button button-primary" href="<?= e(pageUrl('opportunity-form')) ?>">Create your first opportunity</a><?php endif; ?></div>
        <?php else: ?><div class="table-wrap"><table><thead><tr><th>Opportunity</th><th>Category</th><th>Status</th><th>Applications</th><th>Deadline</th><th>Actions</th></tr></thead><tbody><?php foreach ($opportunities as $item): ?><tr><td><?= e($item['title']) ?></td><td><?= e($item['category_name']) ?></td><td><span class="status status-<?= e($item['status']) ?>"><?= e(str_replace('_', ' ', ucfirst($item['status']))) ?></span><?php if ($item['rejection_reason']): ?><small class="row-note"><?= e($item['rejection_reason']) ?></small><?php endif; ?></td><td><?= e($item['application_count']) ?></td><td><?= $item['application_deadline'] ? e(date('M j, Y', strtotime($item['application_deadline']))) : '—' ?></td><td class="action-cell"><?php if (in_array($item['status'], ['draft','rejected'], true)): ?><a class="button button-text" href="<?= e(pageUrl('opportunity-form', ['id' => (int) $item['id']])) ?>">Edit</a><form method="post" action="<?= e(pageUrl('employer')) ?>"><?= formToken() ?><input type="hidden" name="action" value="submit_opportunity"><input type="hidden" name="opportunity_id" value="<?= e($item['id']) ?>"><button class="button button-text" type="submit">Submit for review</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    </div>
    <section class="panel dashboard-section-heading"><div class="panel-heading"><div><span class="eyebrow">RECENT APPLICANTS</span><h2>Applications</h2></div></div>
        <?php if ($applications === []): ?><div class="empty-small"><p>No applications have been received yet.</p></div>
        <?php else: ?><div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Opportunity</th><th>Submitted</th><th>Status</th><th>Update status</th><th>Documents</th></tr></thead><tbody><?php foreach ($applications as $app): ?><tr><td><?= e($app['full_name']) ?><small class="row-note"><?= e($app['email']) ?></small></td><td><?= e($app['title']) ?></td><td><?= e(date('M j, Y', strtotime($app['submitted_at']))) ?></td><td><span class="status status-<?= e($app['status']) ?>"><?= e(str_replace('_', ' ', ucfirst($app['status']))) ?></span></td><td><form class="inline-form" method="post" action="<?= e(pageUrl('employer', ['organization_id' => (int) $organization['id']])) ?>"><?= formToken() ?><input type="hidden" name="action" value="update_application_status"><input type="hidden" name="application_id" value="<?= e($app['id']) ?>"><select name="status" aria-label="New application status" required><option value="" selected disabled>Choose status</option><?php foreach (['under_review','shortlisted','interview','accepted','rejected'] as $status): ?><?php if ($app['status'] !== $status): ?><option value="<?= e($status) ?>"><?= e(str_replace('_', ' ', ucfirst($status))) ?></option><?php endif; ?><?php endforeach; ?></select><button class="button button-text" type="submit">Save</button></form></td><td><?php foreach ($app['documents'] as $document): ?><a class="document-link" href="<?= e(pageUrl('document', ['id' => (int) $document['id']])) ?>"><?= e($document['kind'] === 'cv' ? 'CV' : 'File') ?></a><?php endforeach; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    </section>
</div></section>
